def palindrome(ch):
    reverse = ch[::-1]
    if ch == reverse:
        return True
    else:
        return False
    
while True:
    ch=input("Donner la chaine à verifier : ")
    if (palindrome(ch)):
        print("La chaine est palindrome")
    else:
        print("La chaine est non palindrome")

